/** Exercises a source cancellation callback that waits for its real ORDER consumer to finish. */
class NativeOrderCancellationCallbackHandshakeTest {
	private static final long WAIT_SECONDS = 10L;

	@Test
	void consumerReturnsWhileAcceptedSourceCancellationCallbackWaitsForIt() throws Exception {
		var memory = SealedBoundaryTestSupport.source(List.<Statement>of());
		var strategy = SealedBoundaryTestSupport.nativeStrategy(memory, true);
		var context = new QueryEvaluationContext.Minimal(null);
		var evaluation = SyntheticValueSource.forInvocation(memory, strategy.getQueryExecutionPolicy(),
				EmptyBindingSet.getInstance());
		NativeExecutionContext owner = evaluation.executionContext();
		BlockingCancellationSource source = new BlockingCancellationSource(owner);
		QueryEvaluationStep sourceStep = bindings -> source;
		Order order = new Order(new SingletonSet(), new OrderElem(Var.of("k")));
		QueryEvaluationStep ordered = NativeRootPipeline.order(sourceStep, order, strategy, context);
		assertNotNull(ordered);
		CloseableIteration<BindingSet> result = NativeExecutionContextCarrier.evaluate(
				() -> ordered.evaluate(EmptyBindingSet.getInstance()), evaluation, true);
		assertSame(owner, NativeExecutionContextCarrier.contextOf(result),
				"the actual invocation wrapper retains the same source and ORDER owner");
		ExecutorService workers = Executors.newFixedThreadPool(2);
		Future<Boolean> consume = null;
		Future<Boolean> cancel = null;
		try {
			CloseableIteration<BindingSet> actualResult = result;
			consume = workers.submit(() -> {
				try {
					return actualResult.hasNext();
				} finally {
					source.consumerFinished.countDown();
				}
			});
			assertTrue(source.inputCheckEntered.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"the actual ORDER consumer is inside the child source check");
			cancel = workers.submit(() -> ((CooperativeCancellation) actualResult).requestCancellation());
			assertTrue(source.callbackEntered.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"cancellation reaches the real child source callback on a separate thread");
			assertTrue(source.stopAccepted.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"the child accepted stop before waiting for its consumer to return");
			assertFalse(consume.get(WAIT_SECONDS, TimeUnit.SECONDS),
					"the consumer completes its cooperative stop without waiting for callback retirement");
			assertTrue(cancel.get(WAIT_SECONDS, TimeUnit.SECONDS), "the accepted outer cancellation completes");
			assertTrue(source.callbackReturned.await(WAIT_SECONDS, TimeUnit.SECONDS));
			assertTrue(source.consumerFinished.getCount() == 0L);
			assertTrue(source.accepted.get());
			assertEquals(1, source.cancellationCalls.get());
			assertEquals(1, source.closeCalls.get(), "ORDER and outer owner settle the source exactly once");
			assertTrue(owner.isClosed(), "owner retirement follows callback and consumer settlement");
			assertFalse(result.hasNext());
		} finally {
			source.releaseWaiters();
			result.close();
			workers.shutdownNow();
			workers.awaitTermination(WAIT_SECONDS, TimeUnit.SECONDS);
		}
	}

	private static final class BlockingCancellationSource
			implements CloseableIteration<BindingSet>, CooperativeCancellation, NativeExecutionContextCarrier {
		private final NativeExecutionContext owner;
		private final CountDownLatch inputCheckEntered = new CountDownLatch(1);
		private final CountDownLatch stopAccepted = new CountDownLatch(1);
		private final CountDownLatch callbackEntered = new CountDownLatch(1);
		private final CountDownLatch consumerFinished = new CountDownLatch(1);
		private final CountDownLatch callbackReturned = new CountDownLatch(1);
		private final AtomicInteger cancellationCalls = new AtomicInteger();
		private final AtomicInteger closeCalls = new AtomicInteger();
		private final AtomicBoolean accepted = new AtomicBoolean();
		private final AtomicBoolean closed = new AtomicBoolean();

		private BlockingCancellationSource(NativeExecutionContext owner) {
			this.owner = owner;
		}

		@Override
		public boolean hasNext() {
			inputCheckEntered.countDown();
			await(stopAccepted, "source cancellation to accept stop");
			return false;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException("the accepted cancellation publishes no source row");
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean requestCancellation() {
			cancellationCalls.incrementAndGet();
			callbackEntered.countDown();
			accepted.set(true);
			stopAccepted.countDown();
			try {
				await(consumerFinished, "the real ORDER consumer to finish its cooperative stop");
				return true;
			} finally {
				callbackReturned.countDown();
			}
		}

		@Override
		public NativeExecutionContext executionContext() {
			return owner;
		}

		@Override
		public void close() {
			if (closed.compareAndSet(false, true)) {
				closeCalls.incrementAndGet();
			}
		}

		private void releaseWaiters() {
			stopAccepted.countDown();
			consumerFinished.countDown();
		}
	}

	private static void await(CountDownLatch latch, String message) {
		try {
			if (!latch.await(WAIT_SECONDS, TimeUnit.SECONDS)) {
				throw new IllegalStateException("timed out waiting for " + message);
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException("interrupted while waiting for " + message, interrupted);
		}
	}
}
